  if (!worldStopped() || S.boss.cine) updateBoss(dt);
  if (S.boss.cine) { if (!S.boss.cine.fly) { S.ball.vx = 0; S.ball.vy = 0; } return; }   // đang chiếu cảnh: không điều khiển được
