    if (!worldStopped()) { S.wt += dt; updateEShots(dt); }
    updateObstacles(dt);
    const steps = CHAR === 'zenitsu' ? 20 : CHAR === 'yuutan' ? 10 : 4;   // nhanh gấp 10 thì chia nhỏ bước để không xuyên tường
