      if (!a.tp) {
        a.tp = true;
        const side = -(b.face || 1);
        B.tele.push({ x: u.x, y: u.y, t: .35 });
        u.x = clamp(b.x + side * 80, arenaLo(BOSS_W), arenaHi(BOSS_W)); u.y = clamp(b.y + R, ARENA.floor - 330, ARENA.floor);
        u.vx = u.vy = 0; u.dir = a.dir = Math.sign(b.x - u.x) || 1;
        B.tele.push({ x: u.x, y: u.y, t: .35 }); sfx('tele');
      }
      if (at(W)) { S.bullets.push({ x: u.x + a.dir * 34, y: u.y - 40, vx: a.dir * 620, vy: 0, kind: 'punch', r: 18, sc: 1.6 }); sfx('hit'); }
      if (a.t >= W + .3) endSaiyan(B);
