  ctx.fillStyle = ARMOR; ctx.strokeStyle = '#8a8f98'; ctx.lineWidth = 1.1;
  ctx.beginPath(); ctx.moveTo(-8.5, -35); ctx.lineTo(8.5, -35); ctx.lineTo(7.5, -22); ctx.lineTo(-7.5, -22); ctx.closePath(); ctx.fill(); ctx.stroke();
  ctx.fillStyle = GOLD;
  ctx.fillRect(-7.5, -22, 6, 4); ctx.fillRect(1.5, -22, 6, 4);
  ctx.beginPath(); ctx.ellipse(-8.5, -33.5, 4.6, 3.2, -.35, 0, Math.PI * 2); ctx.ellipse(8.5, -33.5, 4.6, 3.2, .35, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
