  ctx.lineTo(hx - 1, hy - 30); ctx.lineTo(hx + 2, hy - 17); ctx.lineTo(hx + 6, hy - 27); ctx.lineTo(hx + 7, hy - 14); ctx.lineTo(hx + 12, hy - 19);
  ctx.lineTo(hx + 10, hy - 6); ctx.lineTo(hx + 10, hy + 1); ctx.closePath(); ctx.fill();
  ctx.fillStyle = SKIN; ctx.strokeStyle = '#8a5a3a'; ctx.lineWidth = 1.3;
  ctx.beginPath(); ctx.arc(hx + 1, hy, 9.2, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  ctx.fillStyle = o.blue ? '#2f9bff' : DK;
