  for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.ellipse(b.x, b.y - 8 + i * 9, R + 6, 5, Math.sin(S.t * 3 + i) * .15, 0, Math.PI * 2); ctx.stroke(); }
