  for (let i = 0; i < 60; i++) {
    const a = Math.random() * Math.PI * 2, sp = 140 + Math.random() * 420;
    S.parts.push({ x: b.x, y: b.y - 20, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, life: 1, c: ['#6fd0ff', '#ffffff', '#2f9bff'][i % 3], r: 4 + Math.random() * 7, g: 0 });
  }
