// Hồng Liên phá huỷ công trình: bục (kể cả bục di chuyển, bục vỡ), cửa đá, bẫy cưa / cột lửa / chuỳ gai, bãi gai,
// và khoét hố xuống mặt đất (ngoài đấu trường boss). Bị phá là mất hẳn tới khi chơi lại màn.
function crimWreck(x, y, r, dig) {
  const debris = (px, py, c, n) => { for (let i = 0; i < n; i++) { const a = Math.random() * Math.PI * 2, sp = 200 + Math.random() * 420; S.parts.push({ x: px, y: py, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 200, life: 1.1, c: i % 3 ? c : '#ff6a1a', r: 4 + Math.random() * 7, g: 900 }); } };
  let hit = false;
  for (const s of SOLIDS) {
    if (s.gd || s.gate || s.broken || s.open) continue;
    const cx = clamp(x, s.minX, s.maxX), cy = clamp(y, s.minY, s.pts[5]);
    if (Math.hypot(cx - x, cy - y) > r) continue;
    s.broken = S.t + 1e9; hit = true;
    if (s.door) { s.open = true; for (const w of SWITCHES) if (w.door === s) w.on = true; }
    const w = s.maxX - s.minX, h = s.pts[5] - s.minY;
    for (let k = 0; k < Math.max(2, h / 60); k++) debris(s.minX + Math.random() * w, s.minY + Math.random() * h, s.door ? '#7a7e88' : THEMES[MAP].dirt, 8);
  }
  for (const t of TRAP_DEF) {
    if (t.dead) continue;
    const p = t.type === 'flame' ? { x: t.x, y: t.f(t.x) - 20 } : trapPos(t);
    if (Math.hypot(p.x - x, p.y - y) > r + 24) continue;
    t.dead = true; hit = true; debris(p.x, p.y, '#5a5e68', 14);
  }
  for (const sp of SPIKES) if (!S.spikeGone.has(sp) && sp.x1 > x - r && sp.x0 < x + r && Math.abs(sp.f((sp.x0 + sp.x1) / 2) - y) < r) { S.spikeGone.add(sp); hit = true; debris((sp.x0 + sp.x1) / 2, sp.f(sp.x0), '#c8ccd4', 6); }
  if (dig) {
    const gy = groundYAt(x), inArena = x > ARENA.gateX - 60 - r && x < ARENA.r + 80 + r;
    if (!inArena && gy != null && Math.abs(gy - y) < r) {
      const c = CRATERS.find(c => Math.abs(c.x - x) < r * .5);
      if (c) c.d = Math.min(150, c.d + 25); else CRATERS.push({ x, r: r * .7, d: 55 });
      reshapeGround(x - r, x + r); hit = true;
    }
  }
  if (hit) { S.flash = Math.max(S.flash, .15); sfx('stomp'); }
}
function crimBlast(x, y, r, dmg) {
  crimWreck(x, y, r, r >= 90);
  for (const t of nkTouch(x, y, r)) kuHit(t, dmg, { x, y }, false);
  S.ku.booms.push({ x, y, r, t: .45 });
  for (let i = 0; i < 10; i++) { const a = Math.random() * Math.PI * 2, sp = 80 + Math.random() * 260; S.parts.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 80, life: .5, c: ['#ff2a14', '#ffb02a', '#fff0c0'][i % 3], r: 3 + Math.random() * 4, g: 400 }); }
}
// Bất Diệt (Phượng Hoàng, kiểu Supernova của Phoenix Dota 2 / Dark Phoenix): mọi đòn chí mạng — kể cả rơi vực và tự phát nổ
// của Vegeta — chỉ làm Kurumi bùng thành biển lửa rồi tái sinh tại chỗ, đồng thời nổ phản đòn thiêu mọi thứ quanh mình.
function crimRebirth(force) {
  const K = S.ku, b = S.ball;
  if (K.rebT > S.t) return;
  K.rebT = S.t + .3;
  if (fellOff() || b.y > DEATH_Y - 140) { b.y = Math.min(S.safeY, DEATH_Y - 200) - 40; b.vy = 0; }
  S.safe = Math.max(S.safe, 1); K.reborn = .8; K.rebirths = (K.rebirths || 0) + 1;
  const r = force ? 320 : 200;
  K.counter = { r, dmg: force ? 12 : 4 };   // nổ phản đòn ở khung hình sau (không chen vào giữa lượt xử lý của boss)
  K.booms.push({ x: b.x, y: b.y - 20, r, t: .6 });
  for (let i = 0; i < 50; i++) { const a = Math.random() * Math.PI * 2, sp = 200 + Math.random() * 500; S.parts.push({ x: b.x, y: b.y - 20, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, life: .9, c: ['#ff1a1a', '#ff8a1a', '#ffe36a', '#ffffff'][i % 4], r: 4 + Math.random() * 7, g: 0 }); }
  S.flash = Math.max(S.flash, force ? .8 : .35); sfx('boom');
  kuPop(force ? 'Bất Diệt! Đòn chắc chắn chết cũng vô hiệu' : 'Bất Diệt! Phượng Hoàng tái sinh', '#ff9a3a');
}
function updateCrim(dt) {
  {
    const K = S.ku, b = S.ball;
    K.reborn = Math.max(0, (K.reborn || 0) - dt);
    if (K.counter) { const c = K.counter; K.counter = null; for (const t of nkTouch(b.x, b.y - 20, c.r)) kuHit(t, c.dmg, b, false); }
    if (K.crim && !S.dead) {
      // Hoả Giới: đạn / tên của quái bay vào vùng lửa quanh Kurumi là cháy rụi
      for (const q of S.eshots) if (Math.hypot(q.x - b.x, q.y - (b.y - 20)) < 110) { q.dead = true; boltSpark(q.x, q.y, '#ff8a1a', 6); }
      // Thiêu Đốt: boss trúng lửa Hồng Liên cháy âm ỉ, mất máu đều mỗi 0,5 giây trong 5 giây (không né, không khiên nào chặn)
      const U = K.burn;
      if (U) {
        U.d -= dt; U.tick -= dt;
        if (U.d <= 0 || !tAlive(U.t)) K.burn = null;
        else if (U.tick <= 0) { U.tick = .5; const p = tPos(U.t); damageBoss(U.t.ref, 1, 'crim'); for (let i = 0; i < 6; i++) S.parts.push({ x: p.x + (Math.random() - .5) * 50, y: p.y - Math.random() * 60, vx: 0, vy: -160, life: .5, c: i % 2 ? '#ff5a14' : '#ffd23f', r: 3 + Math.random() * 3, g: -60 }); }
      }
    } else K.burn = null;
  }
  const K = S.ku, b = S.ball;
  K.phoenix = Math.max(0, (K.phoenix || 0) - dt);
  for (const o of K.booms) o.t -= dt;
  K.booms = K.booms.filter(o => o.t > 0);
  // hào quang lửa: quái chạm vào là bị thiêu
  if (K.crim && !S.dead) {
    K.burnCd = K.burnCd || new Map();
    crimWreck(b.x, b.y, 40, false);   // lao vào công trình là phá tan
    for (const t of nkTouch(b.x, b.y - 20, 46)) { const c = K.burnCd.get(t.ref) || 0; if (S.t > c) { K.burnCd.set(t.ref, S.t + .35); kuHit(t, 2, b, false); } }
    if (Math.random() < dt * 30) S.parts.push({ x: b.x + (Math.random() - .5) * 40, y: b.y - Math.random() * 60, vx: (Math.random() - .5) * 40, vy: -120 - Math.random() * 80, life: .6, c: Math.random() < .5 ? '#ff5a14' : '#ffd23f', r: 2 + Math.random() * 3, g: -80 });
  }
  const B = K.cbeam;
  if (B) {
    B.t += dt; B.x = b.x + B.d * 26; B.y = b.y - 42;
    B.len = Math.min(B.max, B.len + 3200 * dt);
    if (B.t <= B.dur) for (let s2 = 30; s2 < B.len; s2 += 40) crimWreck(B.x + B.d * s2, B.y, B.w * .8, false);
    if (B.t <= B.dur) for (let s2 = 30; s2 < B.len; s2 += 40) for (const t of nkTouch(B.x + B.d * s2, B.y, B.w)) {
      if (B.hit.has(t.ref)) continue;
      B.hit.add(t.ref); kuHit(t, B.dmg, { x: B.x + B.d * s2, y: B.y }, false);
    }
    if (B.t > B.dur + .3) K.cbeam = null;
  }
  if (K.infernoT > 0) {
    K.infernoT -= dt;
    for (const p of K.pyre || []) p.h = Math.min(1, p.h + dt * 1.2);
    if (K.infernoT <= 0) {
      K.stop = false; applyChar();
      for (const p of K.pyre || []) if (tAlive(p.t)) { const q = tPos(p.t); kuHit(p.t, 12, q, true); crimBlast(q.x, q.y, 110, 2); }
      K.pyre = null; S.flash = Math.max(S.flash, .6); sfx('boom');
    }
  }
  for (const f of K.flames) {
    f.t -= dt; f.tick -= dt;
    if (f.tick <= 0) { f.tick = .3; for (const t of nkTouch(f.x, f.y - 20, 30)) kuHit(t, 2, f, false); }
  }
  K.flames = K.flames.filter(f => f.t > 0);
  for (const m of K.meteors) {
    m.t += dt; m.x += m.vx * dt; m.y += m.vy * dt;
    const gy = groundYAt(m.x);
    if ((gy != null && m.y >= gy - 6) || m.y > S.cam.y + VIEW_H + 80 || nkTouch(m.x, m.y, 26).length) { m.dead = true; crimBlast(m.x, gy != null ? Math.min(m.y, gy - 10) : m.y, 95, 5); sfx('stomp'); }
  }
  K.meteors = K.meteors.filter(m => !m.dead);
}
function drawCrimFx() {
  const K = S.ku;
  if (K.reborn > 0) {
    const b = S.ball, k = 1 - K.reborn / .8;
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    for (const [rr, c] of [[1, 'rgb(255 40 10 / '], [.7, 'rgb(255 160 40 / '], [.4, 'rgb(255 240 200 / ']]) { ctx.strokeStyle = c + ((1 - k) * .8).toFixed(2) + ')'; ctx.lineWidth = 14 * rr; ctx.beginPath(); ctx.arc(b.x, b.y - 20, 40 + k * 260 * rr, 0, Math.PI * 2); ctx.stroke(); }
    ctx.restore();
  }
  if (K.cbeam && K.cbeam.len > 0) {
    ctx.save(); ctx.globalCompositeOperation = 'lighter'; drawKameBeam(K.cbeam); ctx.restore();
  }
  // cột lửa Hoả Ngục mọc trên từng kẻ địch
  if (K.pyre) for (const p of K.pyre) {
    if (!tAlive(p.t)) continue;
    const q = tPos(p.t), h = 120 * p.h;
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    for (const [w, c] of [[26, 'rgb(255 40 10 / .5)'], [16, 'rgb(255 140 30 / .7)'], [7, 'rgb(255 240 180 / .9)']]) {
      ctx.fillStyle = c; ctx.beginPath(); ctx.moveTo(q.x - w, q.y + 26);
      for (let i = 0; i <= 6; i++) ctx.lineTo(q.x - w + i * w / 3, q.y + 26 - h * (i % 2 ? 1 : .7) - Math.sin(S.t * 25 + i + q.x) * 8);
      ctx.lineTo(q.x + w, q.y + 26); ctx.closePath(); ctx.fill();
    }
    ctx.restore();
  }
  // vệt lửa của Bước Lửa
  for (const f of K.flames) {
    const a = Math.min(1, f.t / .5);
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = `rgb(255 80 20 / ${(.55 * a).toFixed(2)})`; ctx.beginPath(); ctx.ellipse(f.x, f.y - 10, 16, 18 + Math.sin(S.t * 20 + f.x) * 5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = `rgb(255 220 120 / ${(.7 * a).toFixed(2)})`; ctx.beginPath(); ctx.ellipse(f.x, f.y - 6, 7, 10, 0, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
  // thiên thạch lửa: đầu đỏ trắng, đuôi lửa dài, mặt đồng hồ nhỏ ở lõi
  for (const m of K.meteors) {
    const a = Math.atan2(m.vy, m.vx);
    ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.translate(m.x, m.y); ctx.rotate(a);
    const g = ctx.createLinearGradient(-110, 0, 0, 0);
    g.addColorStop(0, 'rgb(255 40 10 / 0)'); g.addColorStop(1, 'rgb(255 120 30 / .85)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(-110, -6); ctx.lineTo(0, -16); ctx.lineTo(0, 16); ctx.lineTo(-110, 6); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#fff0c0'; ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    ctx.strokeStyle = '#a00000'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(m.x, m.y, 8, 0, Math.PI * 2); ctx.moveTo(m.x, m.y); ctx.lineTo(m.x + Math.sin(S.t * 9) * 6, m.y - Math.cos(S.t * 9) * 6); ctx.stroke();
  }
  // vụ nổ lửa
  for (const o of K.booms) {
    const k = 1 - o.t / .45;
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, o.r * (.5 + k * .7));
    g.addColorStop(0, `rgb(255 245 200 / ${(1 - k).toFixed(2)})`); g.addColorStop(.4, `rgb(255 120 30 / ${(.8 * (1 - k)).toFixed(2)})`); g.addColorStop(1, 'rgb(200 0 0 / 0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(o.x, o.y, o.r * (.5 + k * .7), 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
}
// hào quang lửa quanh Kurumi Hồng Liên và cánh lửa phượng hoàng khi tái sinh
function drawCrimAura(b) {
  const K = S.ku;
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  drawAura(b.x, b.y + R - 6, 34, 104, 'rgb(255 40 10 / .32)', 0);
  drawAura(b.x, b.y + R - 6, 24, 86, 'rgb(255 160 40 / .38)', 2);
  if (K.phoenix > 0) {
    const a = Math.min(1, K.phoenix / .5);
    for (const s of [-1, 1]) {
      ctx.fillStyle = `rgb(255 120 30 / ${(.5 * a).toFixed(2)})`;
      ctx.beginPath(); ctx.moveTo(b.x, b.y - 40);
      for (let i = 0; i <= 6; i++) ctx.lineTo(b.x + s * (20 + i * 16), b.y - 40 - Math.sin(i / 6 * Math.PI) * 70 + (i % 2 ? 14 : 0) + Math.sin(S.t * 8 + i) * 4);
      ctx.lineTo(b.x + s * 30, b.y - 10); ctx.closePath(); ctx.fill();
    }
  }
  ctx.restore();
}
