  ctx.fillStyle = '#8a1a14'; ctx.beginPath(); ctx.moveTo(sx - 8, sy); ctx.lineTo(-14, hy + 10); ctx.lineTo(-20 + sway * 3, -2); ctx.lineTo(-26 + sway * 4, 0); ctx.quadraticCurveTo(-24 + sway * 3, hy + 30, -10, hy); ctx.fill();
