  ctx.strokeStyle = '#8a3a3a'; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.moveTo(cx + 4, cy + 7.6); ctx.quadraticCurveTo(cx + 6.5, cy + 9, cx + 8.5, cy + 7); ctx.stroke();
