    // xong tràng: quay về chỗ cũ
    Y.fx.push({ k: 'ghost', x: b.x, y: b.y, dir: b.face, pose: 'lunge', t: 0, max: .2 });
    b.x = A.x0; b.y = A.y0; b.vx = 0; b.vy = 0;
    const cz = zs[0];
