    ctx.strokeStyle = 'rgb(255 230 140 / .75)'; ctx.lineWidth = w; ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
    ctx.save(); ctx.rotate(S.t * sp);
