  const [fill, edge] = CHAR === 'saiyan' ? ['rgb(120 200 255 / .22)', '#7cc8ff'] : CHAR === 'pain' ? ['rgb(180 140 255 / .22)', '#b48cff'] : ['rgb(255 170 40 / .22)', '#ffb43a'];
  ctx.fillStyle = fill; ctx.fill();
