    const cf = S.dash ? 5 : S.swing > 0 ? 14 : S.cast > 0 || (S.charging && S.chargeT > BALL_HOLD) ? 21 : S.boom > 0 ? 22 : S.sx.dapT >= 0 ? 18 : apeMoveCF(running, air, b.vy, ph);
