    if (S.sx.blue) { drawAura(b.x, b.y + R, 30, 80, 'rgb(80 170 255 / .3)', 0); drawAura(b.x, b.y + R, 20, 64, 'rgb(200 235 255 / .45)', 2); }
    drawVegetaFig(b.x, fy, d, (1 + sq * .4) * (charged ? 1.04 : 1), S.sx.beam ? 'cast' : pose, { air, run: running, ph, flash: boomK > 0, blue: S.sx.blue });
    // giữ J: cầu Antomic lớn dần trên tay
