  B.inv = kind === 'stomp' || kind === 'tackle' ? .45 : .1;
  const dmg = dmgRoll(base * CH().dmgK * (S.ape > 0 || S.black > 0 || S.ui > 0 ? 2 : 1));
  S.lastDmg = dmg; gainEnergy(5); sfx('hit');
  const me = BET_CUR, O = betOther(me);
